				if (what > overlapIgnored)
				{
					if (what < bestEdgeLength)
					{
						bestEdgeLength = what;

						if ( what * 10.0f < bestPlaneLength )
						{
							if ( p0p1inCrossAxis > 0.0 )
							{
								feature[0] = nativeBlock(prims[0])->getClosestEdge(primPV0.rotation, (NormalId)i, crossAxis) + 6;
								feature[1] = nativeBlock(prims[1])->getClosestEdge(primPV1.rotation, (NormalId)j, -crossAxis) + 6;
							}
							else
							{
								feature[0] = nativeBlock(prims[0])->getClosestEdge(primPV0.rotation, (NormalId)i, -crossAxis) + 6;
								feature[1] = nativeBlock(prims[1])->getClosestEdge(primPV1.rotation, (NormalId)j, crossAxis) + 6;
							}
							planeContact = false;
						}
					}
				}
				else
				{
					 return false;
				}
			}
		}
		return true;
	}


