	bool Camera::nonCharacterZoom(float in)
	{
		G3D::Vector3 lookVector = (*(G3D::CoordinateFrame*)((char*)this+0x1a4)).translation - (*(G3D::CoordinateFrame*)((char*)this+0x174)).translation;

		float currentDistance = lookVector.magnitude();
