		focusToGoal.y = 0.0;
		focusToGoal.unitize();
		focusToGoal.y = newDistance * 0.03f;

		(*(G3D::CoordinateFrame*)((char*)this+0x174)).translation = focusToGoal.direction() * newDistance + (*(G3D::CoordinateFrame*)((char*)this+0x1a4)).translation;

		return true;
