	class Quaternion
	{
		public:
			float x;
			float y;
			float z;
			float w;
			Quaternion(const G3D::Matrix3& rot);
			Quaternion(): x(0), y(0), z(0), w(1) {}
			Quaternion(const G3D::Vector3& vec, float fNum):x(vec.x),y(vec.y),z(vec.z),w(fNum) {}
