			}
			Quaternion operator*(const Quaternion& other) const;
			Quaternion operator+(const Quaternion& other) const
			{
				return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
			}
			Quaternion operator-(const Quaternion& other) const
			{
				return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
			}
			Quaternion& operator*=(float fNum)
			{
				x *= fNum;
				y *= fNum;
				z *= fNum;
				w *= fNum;
				return *this;
			}
			Quaternion& operator+=(const Quaternion& other)
			{
				x = x + other.x;
				y = y + other.y;
				z = z + other.z;
