 Class* service=this->find<Class>();
 if(service==NULL) {
  boost::shared_ptr<Class> s=Creatable<Instance>::create<Class>();
  service=s.get();
  size_t index=getClassIndex<Class>();
  serviceArray[index]=s;
  service->setParent(const_cast<ServiceProvider*>(this));
 }
 return service;
}
