	Team* Teams::getTeamFromTeamColor(BrickColor brickColor)
	{
		for (size_t i = 0; i < numChildren(); i++)
		{
			Team* team = dynamic_cast<Team*>(getChild(i));
			if (team && team->getTeamColor() == brickColor)
				return team;
		}

		return NULL;
