    virtual void v22();
    virtual Vec2 getSize();
    virtual void v24();
    virtual void changed();

    char padding[304];
    Connection connection;
    char padding2[8];
    int state;

    Result process(const Event* event);
};

Result ChatEnter::process(const Event* event)
{
    const int zero = 0;
    if (connection.object != zero)
        connection.object->disconnect();
    connection.reset();

    Vec2 position = getPosition();
    Rect bounds(position, position+getSize());

    if (bounds.pointInRect(event->mousePosition)) {
        switch (event->eventType) {
        case 3:
            if (state != 2) {
                state = 2;
                changed();
            }
            break;
        case 4:
            if (state != 3) {
                state = 3;
                changed();
            }
            break;
        }
        return Result(1, 0);
    }

    if (state != zero) {
        state = zero;
        changed();
    }
    return Result(zero, 0);
}

