#include "gui/Gui.h"
typedef RBX::GuiEvent Event;
typedef RBX::GuiResponse Result;
struct Parent;
struct ParentTable {
 void* reserved[16];
 void (__thiscall* release)(Parent*);
 bool (__thiscall* active)(Parent*);
};
struct GuiItem {
 virtual Result process(const Event&);
 boost::shared_ptr<Parent> parent;
};
struct Parent {
 ParentTable* table;
 char padding[0x12c];
 GuiItem gui;
};
struct Base { Result process(const Event&); };
Result GuiItem::process(const Event& event) {
 if(event.isMouseEvent() && event.eventType==RBX::UIEvent::MOUSE_IDLE)
  return Result::notUsed();
 if(parent) {
  if(parent->table->active(parent.get())) {
   Result result=reinterpret_cast<Base*>(reinterpret_cast<char*>(this)-0x130)->process(event);
   if(result.wasUsed()) return result;
  }
  Result result=parent->gui.process(event);
  if(result.wasUsed()) return result;
  if(parent) parent->table->release(parent.get());
  parent.reset();
 }
 return reinterpret_cast<Base*>(reinterpret_cast<char*>(this)-0x130)->process(event);
}

