	newSet->insert(a);

	if ((oldState == Sim::SLEEPING_CHECKING || oldState == Sim::SLEEPING_DEEPLY) &&
		newState != Sim::SLEEPING_CHECKING && newState != Sim::SLEEPING_DEEPLY) {
