{
	Sim::AssemblyState state = getState(a);

	if (state != Sim::ANCHORED && state != Sim::WAKE_PENDING && state != Sim::RECURSIVE_WAKE_PENDING) {
		changeAssemblyState(a, Sim::WAKE_PENDING);
	}
}

