		(*reinterpret_cast<ContactManager**>(reinterpret_cast<char*>(this)+0x84))->getPrimitivesTouchingExtents(p->getFastFuzzyExtents(), p, (*reinterpret_cast<G3D::Array<Primitive*>*>(reinterpret_cast<char*>(this)+0xf0)));

