		{
			Primitive* currentPrim = (*reinterpret_cast<G3D::Array<Primitive*>*>(reinterpret_cast<char*>(this)+0xf0))[i];

			if (ignoreGroup == NULL || ignoreGroup->find(currentPrim) == ignoreGroup->end())
			{
