struct Property {
    virtual void slot0();
    virtual void slot1();
    virtual void slot2();
    virtual void set(void*, const int&);
};

struct EnumMap {
    char padding0[0x28];
    unsigned int count;
    char padding1[0x8c];
    std::vector<unsigned int> values;
};

struct Descriptor {
    char padding[0x1c];
    Property* property;
    EnumMap* enumMap;

    bool set(void*, unsigned int);
};

bool Descriptor::set(void* instance, unsigned int index)
{
    unsigned int ordinal = index;
    EnumMap* map = enumMap;
    if (ordinal < map->count) {
        index = map->values[ordinal];
        property->set(instance, index);
        return true;
    }
    return false;
}

