	{
		if (value != clearColor)
		{
			clearColor = value;

			raisePropertyChanged(desc_ClearColor);
			fireLightingChanged(false);
			RunService* runService = ServiceProvider::find<RunService>(this);
			if (runService)
				runService->invalidateRunViews();
