	void Camera::setGCameraCoordinateFrame(const G3D::CoordinateFrame& coord)
	{
		if (Math::legalCameraCoord(coord))
		{
			(*(G3D::GCamera*)((char*)this+0x130)).setCoordinateFrame(coord);
		}
		else
