	void Camera::lookAt(const G3D::Vector3& point)
	{
		(*(G3D::CoordinateFrame*)((char*)this+0x1a4)).translation = point;
		(*(G3D::CoordinateFrame*)((char*)this+0x174)).lookAt(point);
