	void PartInstance::setElasticity(float elasticity)
	{
		float newElasticity = G3D::clamp(elasticity, 0.0f, 1.0f);
		if (newElasticity != getElasticity())
		{
			roc_primitive_view()->setElasticity(newElasticity);
