void ResizeTool::capturedDrag(int axisDelta) {
 if (!targetPV.expired()) {
  PartInstance* part=static_cast<PartInstance*>(targetPV.lock().get());
  part->destroyJoints();
  if (part->resize(localNormalId,axisDelta))
   ServiceProvider::create<Soundscape::SoundService>(reinterpret_cast<Instance*>(workspace))->playSound(CLICK_SOUND);
  part->join();
 }
}
int Math::iFloor(float value) { return static_cast<int>(static_cast<float>(::floor(value))); }
void ResizeTool::onMouseMove(const UIEvent& inputObject)
{
	if (!targetPV.expired()) {
		G3D::Vector3 worldNormal = Math::getWorldNormal(localNormalId, targetPV.lock()->getLocation());
		G3D::Ray axisRay = G3D::Ray::fromOriginAndDirection(hitPointGrid, worldNormal);
		G3D::Ray gridRay = getUnitMouseRay(inputObject);
		G3D::Vector3 closePoint = RBX::Math::closestPointOnRay(axisRay, gridRay);
		G3D::Vector3 handleToCurrent = closePoint - hitPointGrid;
		float distanceAlongAxis = axisRay.direction.dot(handleToCurrent);

		float delta = distanceAlongAxis - moveAxis;
		if (delta > 1) {
			int move = (Math::iFloor(delta)/1)*1;
			moveAxis += move;
			capturedDrag(move);
		}
		if (delta < -1) {
			int move = -((Math::iFloor(-delta)/1)*1);
			moveAxis += move;
			capturedDrag(move);
		}
	}
}
}

