void ChatEnter::setState(int value) { if(state!=value) { state=value; changed(); } }

Result ChatEnter::process(const Event* event)
{
    const int zero = 0;
    if (connection.object != zero)
        connection.object->disconnect();
    connection.reset();

    Vec2 position = getPosition();
    Rect bounds(position, position+getSize());

    Result result;
    if (bounds.pointInRect(event->mousePosition)) {
        switch (event->eventType) {
        case 3:
            setState(2);
            break;
        case 4:
            setState(3);
            break;
        }
        result.target=0;
        result.handled=1;
        return result;
    }

    setState(zero);
    result.handled=zero;
    result.target=0;
    return result;
}

