	{
		RBXASSERT(!joined);
		rootInstance->clearCameraIgnoreParts();
		DragUtilities::joinAndStopDragging(dragParts);
		if (DragUtilities::anyPartAlive(dragParts))
		{
			rootInstance->setInsertPoint(DragUtilities::computeExtents(dragParts).topCenter());
		}
		joined = true;
	}

