		{
			G3D::CoordinateFrame newValue = value;
			Math::orthonormalizeIfNecessary(newValue.rotation);
			setPhysics(newValue);

			raisePropertyChanged(prop_CFrame);
			raisePropertyChanged(prop_PositionUi);
		}
