	void Lighting::setAmbientTop(G3D::Color3 value)
	{
		if (value != (*reinterpret_cast<G3D::Color3*>(reinterpret_cast<char*>(this) + 0x270)))
		{
			(*reinterpret_cast<G3D::Color3*>(reinterpret_cast<char*>(this) + 0x270)) = value;

