struct Event { int kind; };
typedef RBX::GuiResponse Result;
struct Widget;
struct S;

struct VTable {
    void *slots0[16];
    void (__thiscall *release)(Widget *);
    void *slots1[8];
    void (__thiscall *changed)(S *);
};

struct Widget {
    VTable *vtable;
    char padding[0x140];
    int menuState;

    void setMenuState(int);
};

struct Shared {
    Widget *pointer;
    void *control;

    void reset();
};

struct Handler {
    int data;
    Shared child;

    Result query(Event*);
};

extern char sourceType;
extern char destinationType;

extern "C" void *__cdecl runtimeCast(
    void *, long, void *, void *, int);

struct S {
    VTable *vtable;
    char padding[0x12c];
    Handler handler;
    char padding2[8];
    int menuState;

    Result f(Event *);
};

Result S::f(Event* event) {
 Widget* previous=reinterpret_cast<Widget*>(dynamic_cast<RBX::UnifiedWidget*>(
  reinterpret_cast<RBX::GuiItem*>(handler.child.pointer)));
 switch(event->kind) {
 case 3:
 case 4: {
  Result result=handler.query(event);
  if(result.wasNotUsed() || result.wasFinished()) {
   if(result.wasFinished()) {
    if(handler.child.pointer) handler.child.pointer->vtable->release(handler.child.pointer);
    handler.child.reset();
   }
   if(menuState!=0) {
    void (__thiscall *changed)(S*)=vtable->changed;
    menuState=0;
    changed(this);
   }
  }
  return result;
 }
 case 5: {
  int state=previous?previous->menuState:0;
  handler.query(event);
  if(previous) {
   Widget* current=reinterpret_cast<Widget*>(dynamic_cast<RBX::UnifiedWidget*>(
    reinterpret_cast<RBX::GuiItem*>(handler.child.pointer)));
   if(current && current!=previous) current->setMenuState(state);
  }
  return Result::used();
 }
 default:return Result::notUsed();
 }
