				updatePV();
				return pv;
			}
			const bool getCanThrottle() const {return *reinterpret_cast<const bool*>(reinterpret_cast<const char*>(this) + 0x30);}
			void accumulateForceAtCofm(const G3D::Vector3&);
			void accumulateForceAtBranchCofm(const G3D::Vector3& force) {
 SimBody* sim = *reinterpret_cast<SimBody**>(reinterpret_cast<char*>(*reinterpret_cast<Body**>(reinterpret_cast<char*>(this) + 0x10)) + 0x2c);
 if (sim) sim->accumulateForceCofm(force);
}
			void accumulateForce(const G3D::Vector3& force, const G3D::Vector3& worldPos)
			{
				SimBody* simBody = root->simBody;
				if (simBody)
					simBody->accumulateForce(force, worldPos);
			}
