			{
				if (root->simBody)
					root->simBody->accumulateTorque(torque);
			}
			void resetAccumulators()
            {
                SimBody* sim = *reinterpret_cast<SimBody**>(reinterpret_cast<char*>(*reinterpret_cast<Body**>(reinterpret_cast<char*>(this) + 0x10)) + 0x2c);
                if (sim) sim->resetAccumulators();
            }
			const G3D::Vector3& getBranchForce() const
