	Instance* MouseCommand::getTopSelectable3d(PartInstance* part)
	{
		Instance* current = part;
		Instance* top = part;

		while (!dynamic_cast<Workspace*>(current->getParent()))
		{
			current = current->getParent();
			if (dynamic_cast<ISelectable3d*>(current))
