Result ChatEnter::process(const Event* event)
{
    const int zero = 0;
    if (connection.object != zero)
        connection.object->disconnect();
    connection.reset();

    Vec2 position = getPosition();
    Rect bounds(position, position+getSize());

    Result result;
    if (bounds.pointInRect(event->mousePosition)) {
        switch (event->eventType) {
        case 3:
            if (state != 2) {
                state = 2;
                changed();
            }
            break;
        case 4:
            if (state != 3) {
                state = 3;
                changed();
            }
            break;
        }
        result.target=0;
        result.handled=1;
        return result;
    }

    if (state != zero) {
        state = zero;
        changed();
    }
    result.handled=zero;
    result.target=0;
    return result;
}

