			std::set<boost::weak_ptr<Instance>>::iterator end = deleteOnDisconnectInstances.end();

			for (; iter != end; iter++)
			{
				boost::shared_ptr<Instance> instance = iter->lock();
				if (instance)
					instance->setParent(NULL);
			}

			deleteOnDisconnectInstances.clear();
