			public:
				//Level(const Level&);
				Level();
			private:
				Level(G3D::ReferenceCountedPointer<TextureProxy> baseTexture, G3D::Color3 color, float specular, float shiny, float reflect, float transparent);
				virtual bool isEmptyLevel() const;
			public:
				virtual ~Level();

				virtual G3D::ReferenceCountedPointer<G3D::Texture> baseTexture(G3D::RenderDevice* rd) const
				{
					if (mBaseTexture.isNull())
						return NULL;
					else
						return mBaseTexture->resolve(rd);
				}

				// Slot3 returns the stored TextureProxy smart pointer; original getter name unknown.
				virtual G3D::ReferenceCountedPointer<TextureProxy> baseTextureProxy() const { return mBaseTexture; }
				virtual void setBaseTexture(G3D::ReferenceCountedPointer<TextureProxy>);

				virtual G3D::ReferenceCountedPointer<G3D::Texture> matte(G3D::RenderDevice* rd) const
				{
					if (mMatte.isNull())
						return NULL;
					else
						return mMatte->resolve(rd);
				}

				virtual const G3D::Color3& color() const
				{
					return mColor;
				}
				virtual float specular() const;
				virtual float shiny() const;
				virtual float reflect() const
				{
					return mReflect;
				}
				virtual float transparent() const
				{
					return mTransparent;
				}
				virtual void configureRenderDevice(G3D::RenderDevice* renderDevice) const;

				//Level& operator=(const Level&);
			};

		private:
			G3D::Array<Level> levels;
		public:
			//Material(const Material&);
			Material();
			const Level& appendEmptyLevel();
			const Level& appendLevel(G3D::Color3, float, float, float, float);
			const Level& appendLevel(G3D::ReferenceCountedPointer<TextureProxy> baseTexture, G3D::Color3 color, float specular, float shiny, float reflect, float transparent);

			virtual ~Material();
			size_t levelCount() const;

			Level& getLevel(int);

			const Level* detailLevel(float lvl) const
			{
				if (levels.size() == 0)
				{
					return NULL;
				}
				else
				{
					int sizeMinusOne = levels.size() - 1;
					int level = lvl * levels.size();

					if (level <= 0)
						level = 0;
					else if (level >= sizeMinusOne)
						level = sizeMinusOne;

					return !levels[level].emptyLevel ? levels.begin() + level : NULL;
				}
			}

			bool veryTransparent() const;
			//Material& operator=(const Material&);
		};
