        var(t, "Asynchronous", settings.asychronous);
        var(t, "Stereo", settings.stereo);
        var(t, "FSAA samples", settings.fsaaSamples);

    t.popIndent();
    t.writeSymbols("}");
    t.writeNewline();
    t.writeNewline();
}

