void RenderDevice::setGamma(
    double              brightness,
    double              gamma) {

    Array<uint16> gammaRamp(256);

    for (int i = 0; i < 256; ++i) {
        gammaRamp[i] =
            (uint16)min(65535, 
                      max(0, 
                      (int)(pow((brightness * (i + 1)) / 256.0, gamma) * 65535 + 0.5)));
	}

    _window->setGammaRamp(gammaRamp);
}


