void RenderDevice::internalSendIndices(
    RenderDevice::Primitive primitive,
    size_t                  indexSize, 
    int                     numIndices, 
    const void*             index) {

    beforePrimitive();
	runObjectShader();

	GLenum i;

	switch (indexSize) {
	case sizeof(uint32):
		i = GL_UNSIGNED_INT;
		break;

	case sizeof(uint16):
		i = GL_UNSIGNED_SHORT;
		break;

	case sizeof(uint8):
		i = GL_UNSIGNED_BYTE;
		break;

	default:
		debugAssertM(false, "Indices must be either 8, 16, or 32-bytes each.");
        i = 0;
	}

    GLenum p = primitiveToGLenum(primitive);

	glDrawElements(p, numIndices, i, index);

    afterPrimitive();
}


