                  "Drawing to a color buffer is only supported by application-created framebuffers!");
    } else {
        alwaysAssertM((b >= BUFFER_CURRENT) && (b <= BUFFER_COLOR15), 
                  "Visible buffers cannot be specified for application-created framebuffers!");
