        mod = mod | KMOD_RALT;
    }
    e.key.keysym.mod = (SDLMod)mod;

    ToUnicode(vkCode, e.key.keysym.scancode, lpKeyState, (LPWSTR)&e.key.keysym.unicode, 1, 0);
