void Win32Window::init(HWND hwnd, bool creatingShareWindow) {

	if (! creatingShareWindow) {
		createShareWindow(settings);
	}

	window = hwnd;

    // Initialize mouse buttons to up
    _mouseButtons[0] = _mouseButtons[1] = _mouseButtons[2] = false;

