// Native 0050eef0: canonicalize a corner, interpolate padding, then restore it.
// Original function name is unknown. Constructor definitions belong to this TU.
#include "G3Dcpp/GImage.cpp"
#include <algorithm>
using namespace G3D;
// Both native helpers contain arithmetic/loops and no C++ throw path.
extern bool rotatedPaste(GImage&,const GImage&,int,int,int,int,int,int,int) throw();
extern Color4uint8 blendPixel(Color4uint8,Color4uint8,float) throw();

void repairAtlasCorner(GImage& image,int x,int y,int width,int height,int angle) {
    int n=(std::max)(width,height)+1;
    GImage work(n,n,4);
    if(angle==0) {
        GImage::pasteSubImage(work,image,0,n-height,x,y,width,height);
    } else if(angle==90 || angle==-90) {
        rotatedPaste(work,image,0,n-width,x,y,width,height,angle);
        std::swap(width,height);
    } else if(angle==180 && image.channels==4) {
        for(int col=0;col<width;++col)
            for(int row=0;row<height;++row)
                work.pixel4(width-col-1,n-row-1)=image.pixel4(x+col,y+row);
    }
    Color4uint8 first=work.pixel4(0,n-height);
    Color4uint8 last=work.pixel4(width-1,n-1);
    for(int row=0;row<n-height;++row) work.pixel4(0,row)=first;
    for(int col=width;col<n;++col) work.pixel4(col,n-1)=last;
    Color4uint8 middle=blendPixel(first,last,0.5f);
    for(int col=1;col<n;++col)
        for(int row=0;row<n-1;++row) work.pixel4(col,row)=middle;
    for(int row=0;row<n;++row) {
        int count=n-1-row;
        for(int i=1;i<count;++i)
            work.pixel4(i,row+i)=blendPixel(work.pixel4(0,row),work.pixel4(count,n-1),
                                          1.0f-static_cast<float>(i)/count);
    }
    if(angle==0) {
        GImage::pasteSubImage(image,work,x,y,0,n-height,width,height);
    } else if(angle==90 || angle==-90) {
        rotatedPaste(image,work,x,y,0,n-height,width,height,-angle);
    } else if(angle==180 && image.channels==4) {
        for(int col=0;col<width;++col)
            for(int row=0;row<height;++row)
                image.pixel4(x+width-1-col,y+height-1-row)=work.pixel4(col,n-height+row);
    }
}

