                index[k + 0] = i + j * sq;
                index[k + 1] = i + (j + 1) * sq;
                index[k + 2] = (i + 1) + (j + 1) * sq;

                // Top triangle
                index[k + 3] = i + j * sq;
                index[k + 4] = (i + 1) + (j + 1) * sq;
                index[k + 5] = (i + 1) + j * sq;

                k += 6;
            }
        }
    }

    // Create data
    std::vector<float> vertex(V * 3), normal(V * 3), texCoord(V * 2), color(V * 4);

