	System::describeSystem(t);
	rd->describeSystem(t);
	nd->describeSystem(t);
}


void describeSystem(
    class RenderDevice*  rd, 
    class NetworkDevice* nd, 
    std::string&        s) {

    TextOutput t;
    describeSystem(rd, nd, t);
    t.commitString(s);
}

