void GImage::convertToL8() {
    switch(channels) {
    case 1:
        return;

    case 3:
        {            
            // Average
            Color3uint8* src = (Color3uint8*)_byte;
            _byte = NULL;
            resize(width, height, 1);
            for (int i = width * height - 1; i >= 0; --i) {
                const Color3uint8   s = src[i];
                uint8&              d = _byte[i]; 
                d = ((int)s.r + (int)s.g + (int)s.b) / 3;
            }
            System::free(src);
        }
        break;

    case 4:
        {            
            // Average
            Color4uint8* src = (Color4uint8*)_byte;
            _byte = NULL;
            resize(width, height, 1);
            for (int i = width * height - 1; i >= 0; --i) {
                const Color4uint8   s = src[i];
                uint8&              d = _byte[i]; 
                d = ((int)s.r + (int)s.g + (int)s.b) / 3;
            }
            System::free(src);
        }
        return;

    default:
        alwaysAssertM(false, "Bad number of channels in input image");
    }
}


void GImage::convertToRGBA() {
    switch(channels) {
    case 1:
        {            
            // Spread
            uint8* old = _byte;
            _byte = NULL;
            resize(width, height, 4);
            for (int i = width * height - 1; i >= 0; --i) {
                const uint8  s = old[i];
                Color4uint8& d = ((Color4uint8*)_byte)[i]; 
                d.r = d.g = d.b = s;
                d.a = 255;
            }
            System::free(_byte);
        }
        break;

    case 3:
        {            
            // Add alpha
            Color3uint8* old = (Color3uint8*)_byte;
            _byte = NULL;
            resize(width, height, 4);
            for (int i = width * height - 1; i >= 0; --i) {
                const Color3uint8   s = old[i];
                Color4uint8&        d = ((Color4uint8*)_byte)[i]; 
                d.r = s.r;
                d.g = s.g;
                d.b = s.b;
                d.a = 255;
            }
            System::free(old);
        }
        break;

    case 4:
        // Already RGBA
        return;

    default:
        alwaysAssertM(false, "Bad number of channels in input image");
    }
}


void GImage::convertToRGB() {
    switch(channels) {
    case 1:
        {            
            // Spread
            uint8* old = _byte;
            _byte = NULL;
            resize(width, height, 3);
            for (int i = width * height - 1; i >= 0; --i) {
                const uint8  s = old[i];
                Color3uint8& d = ((Color3uint8*)_byte)[i]; 
                d.r = d.g = d.b = s;
            }
            System::free(old);
        }
        break;

    case 3:
		return;

    case 4:
		// Strip alpha
        {            
            Color4uint8* old = (Color4uint8*)_byte;
            _byte = NULL;
            resize(width, height, 3);
            for (int i = width * height - 1; i >= 0; --i) {
                const Color4uint8   s = old[i];
                Color3uint8&        d = ((Color3uint8*)_byte)[i]; 
