#include "G3D/g3dmath.h"
#include <stdio.h>

namespace Ogre
{
    extern int fontTextureCounter;

    class VRbxFont
    {
        int subWidth[128];
        int charWidth;
        int charHeight;
        int baseline;
        TexturePtr texture;

    public:
        VRbxFont(const String& filename, G3D::BinaryInput& input);
    };

    typedef char VRbxFont_size_is_0x218[sizeof(VRbxFont) == 0x218 ? 1 : -1];

    VRbxFont::VRbxFont(const String& filename, G3D::BinaryInput& input)
        : texture()
    {
        input.readInt32();

        for (int c = 0; c < 128; ++c)
            subWidth[c] = input.readUInt16();

        baseline = input.readUInt16();
        int textureWidth = input.readUInt16();
        charWidth = textureWidth / 16;
        charHeight = textureWidth / 16;

        int width = G3D::ceilPow2(charWidth * 16);
        int height = G3D::ceilPow2(charHeight * 8);

        const G3D::uint8* pixels =
            static_cast<const G3D::uint8*>(input.getCArray()) + input.getPosition();

        char textureName[8];
        _snprintf(textureName, 8, "ft%d", fontTextureCounter++);
        texture = TextureManager::getSingleton().create(textureName, "General");

        DataStreamPtr stream(new MemoryDataStream(
            const_cast<G3D::uint8*>(pixels), width * height, false));
        texture.getPointer()->loadRawData(stream, width, height, PF_A8);
    }
}

