    if (menu == NULL)
        return;

    for (UINT index = 0; index < (UINT)::GetMenuItemCount(menu->m_hMenu); ++index)
    {
        CEnabledCmdUI state;
        state.m_nID = ::GetMenuItemID(menu->m_hMenu, index);

        if (state.m_nID != 0)
        {
            if (state.m_nID == (UINT)-1)
            {
