                    (MenuCommandTargetProbe*)AfxGetMainWnd();

                target->table->onCmdMsg(target, state.m_nID,
                    CN_UPDATE_COMMAND_UI, &state, NULL);
                ::EnableMenuItem(menu->m_hMenu, index,
                    MF_BYPOSITION | (state.m_bEnabled ? MF_ENABLED : MF_DISABLED));
            }
        }
    }

